fn numpy_where(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // Check if all input vectors have the same length
    if condition.len() != x.len() || condition.len() != y.len() {
        return Vec::new(); // Return an empty vector if lengths do not match
    }

    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(condition.len());

    // Iterate through the indices and select values based on the condition
    for i in 0..condition.len() {
        if condition[i] {
            result.push(x[i]); // Take from x if condition is true
        } else {
            result.push(y[i]); // Take from y if condition is false
        }
    }

    result // Return the resulting vector
}